#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string s;
    getline(cin, s);

    for (int i = static_cast<int>(s.size()) - 1; i >= 0; --i) {
        if (s[i] == '?' || isspace(static_cast<unsigned char>(s[i])))
            continue;

        char c = static_cast<char>(tolower(static_cast<unsigned char>(s[i])));
        cout << ((c == 'a' || c == 'e' || c == 'i' ||
                  c == 'o' || c == 'u' || c == 'y') ? "YES" : "NO");
        break;
    }

    return 0;
}

